#!/usr/bin/env bash
set -Eeuo pipefail

# Qwen Image 2.1 — automatic Vast.ai setup
# Assumes you selected a ComfyUI-based Vast template yourself.

LOG=/workspace/qwen_autosetup.log
mkdir -p /workspace
exec > >(tee -a "$LOG") 2>&1

echo "============================================================"
echo "Qwen Image 2.1 auto-setup started: $(date)"
echo "============================================================"

# 1) Locate ComfyUI
COMFY_DIR=""
for p in /workspace/ComfyUI /opt/ComfyUI /root/ComfyUI /ComfyUI; do
  if [ -d "$p" ]; then COMFY_DIR="$p"; break; fi
done

if [ -z "$COMFY_DIR" ]; then
  echo "Waiting for ComfyUI directory to appear..."
  for i in $(seq 1 60); do
    COMFY_DIR=$(find /workspace /opt /root -maxdepth 3 -type d -name ComfyUI 2>/dev/null | head -n 1 || true)
    [ -n "$COMFY_DIR" ] && break
    sleep 5
  done
fi

if [ -z "$COMFY_DIR" ] || [ ! -d "$COMFY_DIR" ]; then
  echo "ERROR: ComfyUI directory not found. Use a ComfyUI Vast template."
  exit 1
fi

echo "ComfyUI found at: $COMFY_DIR"

# 2) Make only the required model/workflow directories
mkdir -p "$COMFY_DIR/models/diffusion_models"
mkdir -p "$COMFY_DIR/models/text_encoders"
mkdir -p "$COMFY_DIR/models/vae"
mkdir -p "$COMFY_DIR/user/default/workflows"

# 3) Download helper: skip valid existing files; resume partial files
fetch() {
  local url="$1"
  local dst="$2"
  local min_bytes="$3"

  if [ -f "$dst" ]; then
    local size
    size=$(stat -c%s "$dst" 2>/dev/null || echo 0)
    if [ "$size" -ge "$min_bytes" ]; then
      echo "OK already present: $(basename "$dst") ($(numfmt --to=iec "$size" 2>/dev/null || echo "$size bytes"))"
      return 0
    fi
    echo "Partial/incomplete file found; resuming: $(basename "$dst")"
  fi

  echo "Downloading: $(basename "$dst")"
  if command -v wget >/dev/null 2>&1; then
    wget -c --tries=10 --timeout=30 --show-progress "$url" -O "$dst"
  elif command -v curl >/dev/null 2>&1; then
    curl -L --fail --retry 10 --retry-delay 3 -C - "$url" -o "$dst"
  else
    echo "ERROR: wget/curl not available."
    exit 1
  fi
}

# 4) Qwen Image 2.1 — ONLY 3 required model files
HF="https://huggingface.co/Comfy-Org/Qwen-Image-2.1/resolve/main"

fetch "$HF/diffusion_models/qwen_image_2.1_int8_convrot.safetensors"       "$COMFY_DIR/models/diffusion_models/qwen_image_2.1_int8_convrot.safetensors"       6000000000

fetch "$HF/text_encoders/qwen3vl_8b_int8_convrot.safetensors"       "$COMFY_DIR/models/text_encoders/qwen3vl_8b_int8_convrot.safetensors"       8000000000

fetch "$HF/vae/qwen_image_2.1_vae_bf16.safetensors"       "$COMFY_DIR/models/vae/qwen_image_2.1_vae_bf16.safetensors"       500000000

# 5) Install the workflow automatically (embedded; no JSON upload needed)
WORKFLOW="$COMFY_DIR/user/default/workflows/Qwen_FaceHead_Outfit.json"
echo '' | base64 -d > "$WORKFLOW"
cp -f "$WORKFLOW" /workspace/Qwen_FaceHead_Outfit.json

echo "Workflow installed: $WORKFLOW"

# 6) Sanity check for current Qwen 2.1 core nodes
if ! grep -Rqs "TextEncodeQwenImage21" "$COMFY_DIR/comfy_extras" 2>/dev/null; then
  echo "WARNING: TextEncodeQwenImage21 not found in this ComfyUI build."
  echo "Attempting a safe ComfyUI update..."
  if [ -d "$COMFY_DIR/.git" ] && command -v git >/dev/null 2>&1; then
    (cd "$COMFY_DIR" && git pull --ff-only) || true
    PYBIN=$(command -v python3 || command -v python || true)
    if [ -n "$PYBIN" ] && [ -f "$COMFY_DIR/requirements.txt" ]; then
      "$PYBIN" -m pip install -r "$COMFY_DIR/requirements.txt" || true
    fi
    echo "ComfyUI was updated. If the Qwen nodes are still missing in the browser, restart the instance once."
  else
    echo "Could not auto-update this template's ComfyUI checkout."
  fi
fi

# 7) Completion marker
cat > /workspace/QWEN_SETUP_DONE.txt <<EOF
Qwen Image 2.1 setup finished successfully at $(date)
ComfyUI: $COMFY_DIR
Workflow: $WORKFLOW
Models:
- qwen_image_2.1_int8_convrot.safetensors
- qwen3vl_8b_int8_convrot.safetensors
- qwen_image_2.1_vae_bf16.safetensors
EOF

echo "============================================================"
echo "SETUP COMPLETE"
echo "Open/refresh ComfyUI and load workflow: Qwen_FaceHead_Outfit"
echo "Log: $LOG"
echo "Marker: /workspace/QWEN_SETUP_DONE.txt"
echo "============================================================"
